export const AGES = [16,17,18,19,20,21,22,24,25,27,29,30,32,34,36,38,40,42,44,46,48,50,53,56,59,62,65,68,71,74,77,80];
const C = (id,title,desc,result,effects={},extra={}) => {
  // Emphasize each choice's main value without filling every meter over 32 chapters.
  // Money is literal万円; fatigue/cost deltas remain literal, too.
  const gains=Object.entries(effects).filter(([key,value])=>key!=='money'&&value>0);
  const focus=gains.reduce((best,item)=>!best||item[1]>best[1]?item:best,null);
  const balanced=Object.fromEntries(Object.entries(effects).map(([key,value])=>[
    key,key==='money'||value<=0?value:key===focus?.[0]?Math.min(5,Math.max(3,Math.round(value/2))):1
  ]));
  return {id,title,desc,result,effects:balanced,...extra};
};
const E = (age,id,category,title,lead,text,scene,choices,when) => ({age,id,category,title,lead,text,scene,choices,...(when?{when}:{})});
